import type { Diagnostic } from 'caliper-docgen-napi'
import type { DiagnosticLevel } from './diagnostics.js'

export interface CaliperDocgenOptions {
  srcDirs: string[]
  exclude?: string[]
  /** Leave out the HTML attributes a component inherits from its element. Same as `htmlAttributes: 'none'`. */
  skipHtmlProps?: boolean
  /** Which HTML attributes to list: all of them (`'full'`, the default), a compact subset (`'curated'`: handlers, `aria-*`, `ref`, common attributes) or none. Wins over `skipHtmlProps`. */
  htmlAttributes?: 'curated' | 'full' | 'none'
  /**
   * The least severe extraction diagnostic to log, once each: `'error'`, `'warn'` (the default), `'info'`, or
   * `'silent'` to log none.
   */
  logLevel?: DiagnosticLevel
  /** Called once for every diagnostic, whatever `logLevel` is. */
  onDiagnostic?: (diagnostic: Diagnostic) => void
  /** Assign each component its react-docgen-typescript docs as `__docgenInfo`, for Storybook without a docgen server. */
  injectDocgenInfo?: boolean
  /**
   * Read and write the on-disk caches under `node_modules/.cache`. Default: `true`; `false` reads and writes nothing
   * there and parses everything every run. The output is the same.
   */
  cache?: boolean
  /** Load the type declarations your props reference from installed packages. On by default; `false` skips it. */
  loadDependencies?: boolean
  /**
   * Which inherited sources of more than 30 props to list as one inherited layer instead of prop by prop: those from
   * loaded dependencies (the default), every inherited source, or none.
   */
  collapseInheritedProps?: 'dependencies' | 'all' | 'none'
}

import { describe, expect, test } from 'vitest'
import { brandTokens, orinPreset, techworxPreset, type Brand } from './index.ts'
import { sizeValue } from './scales.ts'
import { foldAt } from './fold.ts'
import { compactAt } from './ui/popup/presentation.ts'

// The two width steps are the whole width vocabulary of a page: tablet and desktop, both min-width. Conditions written as
// max-width or with `width <=` bring back an inclusive "narrow" boundary, so a new one fails here.

const stepsOf = (preset: typeof orinPreset) => {
  const theme = preset.theme?.extend
  return { breakpoints: theme?.breakpoints ?? {}, containers: theme?.containers ?? {} }
}

const maxWidthConditions = (brand: Brand) =>
  Object.entries(brandTokens(brand).conditions)
    .filter(([, value]) => typeof value === 'string' && /max-width|width\s*<=/u.test(value))
    .map(([name]) => name)

describe('the two width steps', () => {
  test.each([
    ['orin', orinPreset],
    ['twx', techworxPreset],
  ] as const)('%s defines exactly tablet and desktop, for breakpoints and containers', (brand, preset) => {
    const { breakpoints, containers } = stepsOf(preset)
    expect(Object.keys(breakpoints)).toStrictEqual(['tablet', 'desktop'])
    expect(Object.keys(containers)).toStrictEqual(['tablet', 'desktop'])
    expect(breakpoints).toStrictEqual(containers)
    expect(Object.values(breakpoints)[0]).toBe(sizeValue(brand, 'compactAt'))
  })

  test.each(['orin', 'twx'] as const)('%s has no max-width or "width <=" condition', (brand) => {
    expect(maxWidthConditions(brand)).toStrictEqual([])
  })

  test.each(['orin', 'twx'] as const)('the presentation chooser agrees with the %s tablet step', (brand) => {
    expect(`${compactAt}px`).toBe(sizeValue(brand, 'compactAt'))
  })
})

describe('the default fold width', () => {
  test.each(['orin', 'twx'] as const)(
    '%s has one fold token and one container condition that read the same width',
    (brand) => {
      const { conditions, tokens } = brandTokens(brand)
      expect(tokens.sizes.fold?.value).toBe(foldAt)
      expect(conditions.fromFold).toBe(`@container (width >= ${foldAt})`)
    },
  )

  test.each(['orin', 'twx'] as const)('%s no longer defines the compact and single conditions', (brand) => {
    const names = Object.keys(brandTokens(brand).conditions)
    expect(names).not.toContain('compact')
    expect(names).not.toContain('single')
  })
})

describe('the touch conditions', () => {
  test.each(['orin', 'twx'] as const)('%s answers a coarse primary or any attached pointer', (brand) => {
    expect(brandTokens(brand).conditions.coarse).toBe('@media (pointer: coarse), (any-pointer: coarse)')
  })
})
